Np = 1000;
%q = (0:4*Np)/(Np+1);
Emax = 800;
en = (0:Np)*Emax/(Np+1);
eCut = 400;
peak_pos = 0.8;
%      -,e0,  gamma,A,-, peak_pos
par = [1,eCut,20,   1,0, peak_pos];
%en=eCut*ones(size(q));
q=ones(size(en));
%enAv = sum(en)/numel(en);
wt = test_dsho_fun(q,en,par);
%plot(q,wt);
plot(en,wt); %[output:1b9c8ae3]

Norm = sum(wt)*max(en)/Np %[output:089a8991]



